// Base outlets stay fixed above. Slots ("- 2"/"- 3") added by Account Supervisors
// live in the DB and are merged in here at runtime so all lookups see them.
let RUNTIME_OUTLETS = [...OUTLET_DATA];
function mergeSlots(slots) {
  const extra = Array.isArray(slots) ? slots : [];
  RUNTIME_OUTLETS = [...OUTLET_DATA, ...extra];
  return RUNTIME_OUTLETS;
}

