function isDeployUnlocked(applicantStatus, role) {
  if (["ACCOUNT SUPERVISOR", "MIS", "OPERATION ENCODER"].includes(role))
    return true;
  if (!applicantStatus || applicantStatus === "") return true;
  return applicantStatus === "Onboarded";
}

function formatDate(dateStr) {
  if (!dateStr) return "—";
  const d = new Date(dateStr);
  if (isNaN(d)) return "—";
  return d.toLocaleDateString("en-PH", {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
}

function calcDaysUndeployed(undeployDate, deployStatus) {
  if (deployStatus === "Deployed" || !undeployDate) return null;
  const from = new Date(undeployDate);
  if (isNaN(from)) return null;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  from.setHours(0, 0, 0, 0);
  const diff = Math.floor((today - from) / (1000 * 60 * 60 * 24));
  return diff >= 0 ? diff : 0;
}

function getDaysBadgeColor(days) {
  if (days === null) return null;
  if (days <= 7) return { bg: "#fff9c4", color: "#f57f17", border: "#ffe082" };
  if (days <= 30) return { bg: "#ffe0b2", color: "#e65100", border: "#ffcc80" };
  return { bg: "#ffcdd2", color: "#b71c1c", border: "#ef9a9a" };
}

function todayISO() {
  return new Date().toISOString().split("T")[0];
}

// ═════════════════════════════════════════════════════════════════════════════
// 3. DATA BUILDING FUNCTIONS
// ═════════════════════════════════════════════════════════════════════════════

function buildAssignmentMaps(allData) {
  const efcAll = allData.filter(
    (e) => e.clientAssigned?.toUpperCase() === "ECOSSENTIAL FOODS CORP",
  );

  const merchandisers = efcAll.filter(
    (e) =>
      ["Merchandiser", "CVS Merchandiser", "Repacker"].includes(e.position) &&
      e.status?.toLowerCase() === "active",
  );

  const efcApplicants = efcAll.filter(
    (e) =>
      ["Merchandiser", "CVS Merchandiser", "Repacker"].includes(e.position) &&
      e.status?.toLowerCase() === "applicant",
  );

  const coordinators = efcAll.filter(
    (e) =>
      ["Tactical Coordinator", "Account Coordinator"].includes(e.position) &&
      e.status?.toLowerCase() === "active",
  );

  const assignments = {};

  // Map employed merchandisers
  merchandisers.forEach((emp) => {
    const names = new Set();
    if (emp.outletsAssigned?.length > 0)
      emp.outletsAssigned.forEach((n) => names.add(n));
    if (names.size === 0 && emp.outletAssignmentHistory?.length > 0) {
      const lat =
        emp.outletAssignmentHistory[emp.outletAssignmentHistory.length - 1];
      if (lat?.outletName) names.add(lat.outletName);
    }
    names.forEach((outletName) => {
      const m = RUNTIME_OUTLETS.find((o) => o.outlet === outletName);
      if (m) {
        assignments[m.id] = {
          employeeId: emp._id,
          employeeNo: emp.employeeNo || "",
          employeeName: `${emp.lastName} ${emp.firstName}`,
          firstName: emp.firstName || "",
          lastName: emp.lastName || "",
          suffix: emp.suffix || "",
          modeOfDisbursement: emp.modeOfDisbursement || "",
          accountNumber: emp.accountNumber || "",
          deployStatus: emp.deployStatus || "Undeployed",
          deploymentType: emp.deploymentType || "Stationary",
          employmentStatus: emp.employmentStatus || "Regular",
          rateCardId: emp.rateCardId || null,
          rateCardId: emp.rateCardId ?? "",
          deployDate: emp.deployDate || null,
          undeployDate: emp.undeployDate || null,
          applicantStatus: emp.applicantStatus || "",
          backOutReason: emp.backOutReason || "",
          targetOnboardDate: emp.targetOnboardDate || null,
          temporaryDeployEndDate: emp.temporaryDeployEndDate || null,
          isApplicant: false,
          incomingApplicantId: null,
          incomingApplicantName: null,
          incomingApplicantStatus: "",
        };
      }
    });
  });

  // Map applicants
  efcApplicants.forEach((emp) => {
    const names = new Set();
    if (emp.outletsAssigned?.length > 0)
      emp.outletsAssigned.forEach((n) => names.add(n));
    if (names.size === 0 && emp.outletAssignmentHistory?.length > 0) {
      const lat =
        emp.outletAssignmentHistory[emp.outletAssignmentHistory.length - 1];
      if (lat?.outletName) names.add(lat.outletName);
    }
    names.forEach((outletName) => {
      const m = RUNTIME_OUTLETS.find((o) => o.outlet === outletName);
      if (!m) return;
      if (assignments[m.id]) {
        assignments[m.id].incomingApplicantId = emp._id;
        assignments[m.id].incomingApplicantName =
          `${emp.lastName} ${emp.firstName}`;
        assignments[m.id].incomingApplicantStatus = emp.applicantStatus || "";
        assignments[m.id].incomingBackOutReason = emp.backOutReason || "";
        assignments[m.id].incomingTargetOnboardDate =
          emp.targetOnboardDate || null;
      } else {
        assignments[m.id] = {
          employeeId: emp._id,
          employeeName: `${emp.lastName} ${emp.firstName}`,
          firstName: emp.firstName || "",
          lastName: emp.lastName || "",
          suffix: emp.suffix || "",
          modeOfDisbursement: emp.modeOfDisbursement || "",
          accountNumber: emp.accountNumber || "",
          deployStatus: emp.deployStatus || "Undeployed",
          deploymentType: emp.deploymentType || "Stationary",
          employmentStatus: emp.employmentStatus || "Regular",
          rateCardId: emp.rateCardId || null,
          rateCardId: emp.rateCardId ?? "",
          deployDate: emp.deployDate || null,
          undeployDate: emp.undeployDate || null,
          applicantStatus: emp.applicantStatus || "",
          backOutReason: emp.backOutReason || "",
          targetOnboardDate: emp.targetOnboardDate || null,
          temporaryDeployEndDate: emp.temporaryDeployEndDate || null,
          isApplicant: true,
          incomingApplicantId: null,
          incomingApplicantName: null,
          incomingApplicantStatus: "",
        };
      }
    });
  });

  // Map coordinators
  const coordAssignments = {};
  coordinators.forEach((emp) => {
    if (emp.outletsAssigned?.length > 0) {
      emp.outletsAssigned.forEach((outletName) => {
        const m = RUNTIME_OUTLETS.find((o) => o.outlet === outletName);
        if (m) {
          const safeKey = outletName.replace(/\./g, "_");
          coordAssignments[m.id] = {
            employeeId: emp._id,
            employeeName: `${emp.firstName} ${emp.lastName}`,
            status: emp.outletStatusMap?.[safeKey] || "Active",
          };
        }
      });
    }
  });

  return {
    merchandisers,
    coordinators,
    assignments,
    coordAssignments,
    efcApplicants,
  };
}

function buildSummaryData(employees, outletAssignments, type = "MERCHANDISER") {
  const map = {};
  Object.entries(outletAssignments).forEach(([outletId, a]) => {
    const empId = a.employeeId;
    const info = RUNTIME_OUTLETS.find((o) => o.id === parseInt(outletId));
    if (!info) return;
    if (!map[empId]) {
      map[empId] = {
        employeeId: empId,
        employeeName: a.employeeName,
        outlets: [],
        status: a.deployStatus || a.status,
      };
    }
    map[empId].outlets.push({
      outletName: info.outlet,
      account: info.account,
      status: type === "MERCHANDISER" ? a.deployStatus : a.status,
    });
  });

  const assigned = Object.values(map).sort((a, b) =>
    a.employeeName.localeCompare(b.employeeName),
  );

  const assignedIds = new Set(Object.keys(map));
  const floating = employees
    .filter((e) => !assignedIds.has(e._id))
    .map((e) => ({
      employeeId: e._id,
      employeeName: `${e.firstName} ${e.lastName}`,
      outlets: [],
      position: e.position || "",
    }))
    .sort((a, b) => a.employeeName.localeCompare(b.employeeName));

  return { assigned, floating };
}

// ═════════════════════════════════════════════════════════════════════════════
// 4. REACT COMPONENTS
// ═════════════════════════════════════════════════════════════════════════════

const BackOutReasonField = React.memo(function BackOutReasonField({
  value,
  onChange,
  hasError,
}) {
  return (
    <TextField
      label="Reason for Back Out *"
      fullWidth
      multiline
      rows={2}
      defaultValue={value}
      onBlur={(e) => onChange(e.target.value)}
      placeholder="Enter reason why applicant backed out..."
      error={!value && hasError}
      helperText={
        !value
          ? "⚠ Required — enter the reason for backing out"
          : `${value.length} characters`
      }
      FormHelperTextProps={{ sx: { color: !value ? "#d32f2f" : "#888" } }}
      sx={{
        "& .MuiOutlinedInput-root": {
          backgroundColor: "#fff8f8",
          border: "1px solid #ef9a9a",
        },
      }}
    />
  );
});

const TerminateReasonField = React.memo(function TerminateReasonField({
  value,
  onChange,
  hasError,
}) {
  return (
    <TextField
      label="Reason for Termination *"
      fullWidth
      multiline
      rows={2}
      defaultValue={value}
      onBlur={(e) => onChange(e.target.value)}
      placeholder="Enter the specific reason for termination..."
      error={!value && hasError}
      helperText={
        !value
          ? "⚠ Required — provide the reason for termination"
          : `${value.length} characters`
      }
      FormHelperTextProps={{ sx: { color: !value ? "#d32f2f" : "#888" } }}
      sx={{ "& .MuiOutlinedInput-root": { backgroundColor: "#fff8f0" } }}
    />
  );
});

// ═════════════════════════════════════════════════════════════════════════════
// 5. MAIN COMPONENT - OutletListRoving
//    Roving-package manager. No HR pipeline, no merchandiser assignment, no HC.
//    Account Supervisors group several outlets into one roving "package".
//    Each package gets an auto-generated Roving ID (assigned by the backend).
// ═════════════════════════════════════════════════════════════════════════════

export default function OutletListRoving() {
  // ── State ──────────────────────────────────────────────────────────────────
  const [rovingGroups, setRovingGroups] = useState([]);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [loading, setLoading] = useState(false);

  // Filters
  const [filterRegion, setFilterRegion] = useState("ALL");
  const [filterSupervisor, setFilterSupervisor] = useState("ALL");
  const [searchText, setSearchText] = useState("");

  // Create / Edit roving-package modal
  const [openGroupModal, setOpenGroupModal] = useState(false);
  const [editingGroup, setEditingGroup] = useState(null); // null = creating
  const [groupName, setGroupName] = useState("");
  const [groupSupervisor, setGroupSupervisor] = useState("");
  const [groupOutlets, setGroupOutlets] = useState([]); // array of outlet objects
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState("");

  // Delete confirm
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [deleting, setDeleting] = useState(false);

  // Snackbar
  const [snack, setSnack] = useState({ open: false, msg: "", sev: "success" });
  const notify = (msg, sev = "success") => setSnack({ open: true, msg, sev });

  // ── Permissions ──────────────────────────────────────────────────────────
  const role = localStorage.getItem("roleAccount");
  const canEdit = ["ACCOUNT SUPERVISOR", "MIS", "OPERATION ENCODER"].includes(
    role,
  );

  const API = "https://api-map.bmphrc.com";

  // ── Sidebar sync ───────────────────────────────────────────────────────────
  useEffect(() => {
    const check = () =>
      setSidebarOpen(localStorage.getItem("sidebarOpen") === "true");
    check();
    window.addEventListener("storage", check);
    const iv = setInterval(check, 100);
    return () => {
      window.removeEventListener("storage", check);
      clearInterval(iv);
    };
  }, []);

  // ── Data loading ───────────────────────────────────────────────────────────
  // Merge any outlet slots ("- 2"/"- 3") so the outlet picker sees them too.
  const fetchSlots = async () => {
    try {
      const slotRes = await axios.get(`${API}/outlet-slots`);
      mergeSlots(slotRes.data?.data || []);
    } catch (slotErr) {
      console.error("Failed to fetch outlet slots:", slotErr);
      mergeSlots([]);
    }
  };

  const fetchGroups = async () => {
    try {
      setLoading(true);
      const res = await axios.get(`${API}/roving-groups`);
      setRovingGroups(res.data?.data || []);
    } catch (e) {
      console.error("Failed to fetch roving groups:", e);
      setRovingGroups([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSlots();
    fetchGroups();
  }, []);

  // ── Option lists ─────────────────────────────────────────────────────────
  const supervisorOptions = Array.from(
    new Set(
      RUNTIME_OUTLETS.map((o) => o.accountSupervisor).filter(
        (s) => s && s.trim() !== "",
      ),
    ),
  ).sort();

  const regionOptions = Array.from(
    new Set(
      RUNTIME_OUTLETS.map((o) => o.region).filter((s) => s && s.trim() !== ""),
    ),
  ).sort();

  // ── Rows (one per roving package) ──────────────────────────────────────────
  const rows = rovingGroups
    .map((g, i) => {
      const members = (g.outlets || [])
        .map((name) => RUNTIME_OUTLETS.find((o) => o.outlet === name))
        .filter(Boolean);
      return {
        id: g._id || `tmp-${i}`,
        _raw: g,
        rovingId: g.rovingId || "—",
        packageName: g.name || "(unnamed)",
        region: g.region || members[0]?.region || "",
        accountSupervisor: g.accountSupervisor || "",
        _members: members,
        _memberNames: g.outlets || [],
      };
    })
    .filter((r) => {
      if (filterRegion !== "ALL" && r.region !== filterRegion) return false;
      if (
        filterSupervisor !== "ALL" &&
        r.accountSupervisor !== filterSupervisor
      )
        return false;
      const q = searchText.trim().toLowerCase();
      if (q) {
        const hay = [
          r.rovingId,
          r.packageName,
          r.region,
          r.accountSupervisor,
          ...r._memberNames,
        ]
          .filter(Boolean)
          .join(" ")
          .toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    })
    .map((r, idx) => ({ ...r, count: idx + 1 }));

  const totalPackages = rows.length;
  const totalOutlets = rows.reduce((s, r) => s + r._memberNames.length, 0);

  // ── Modal handlers ─────────────────────────────────────────────────────────
  const openCreate = () => {
    setEditingGroup(null);
    setGroupName("");
    setGroupSupervisor("");
    setGroupOutlets([]);
    setFormError("");
    setOpenGroupModal(true);
  };

  const openEdit = (group) => {
    setEditingGroup(group);
    setGroupName(group.name || "");
    setGroupSupervisor(group.accountSupervisor || "");
    setGroupOutlets(
      (group.outlets || [])
        .map((name) => RUNTIME_OUTLETS.find((o) => o.outlet === name))
        .filter(Boolean),
    );
    setFormError("");
    setOpenGroupModal(true);
  };

  const closeGroupModal = () => {
    if (saving) return;
    setOpenGroupModal(false);
    setEditingGroup(null);
  };

  const saveGroup = async () => {
    if (!groupSupervisor) {
      setFormError("Please select an Account Supervisor.");
      return;
    }
    if (groupOutlets.length < 2) {
      setFormError("A roving package needs at least 2 outlets.");
      return;
    }

    // Roving ID is assigned automatically by the backend — not sent from here.
    const payload = {
      name: groupName.trim(),
      accountSupervisor: groupSupervisor,
      region: groupOutlets[0]?.region || "",
      outlets: groupOutlets.map((o) => o.outlet),
      updatedBy: localStorage.getItem("adminFullName") || "Unknown",
      updatedByRole: role || "",
    };

    try {
      setSaving(true);
      setFormError("");
      if (editingGroup?._id) {
        await axios.put(`${API}/roving-groups/${editingGroup._id}`, payload);
        notify("Roving package updated.");
      } else {
        const res = await axios.post(`${API}/roving-groups`, payload);
        notify(
          `Roving package created${res.data?.data?.rovingId ? ` (${res.data.data.rovingId})` : ""}.`,
        );
      }
      setOpenGroupModal(false);
      setEditingGroup(null);
      await fetchGroups();
    } catch (e) {
      console.error("Failed to save roving package:", e);
      setFormError(
        e.response?.data?.message || "Failed to save. Please try again.",
      );
    } finally {
      setSaving(false);
    }
  };

  const confirmDelete = async () => {
    if (!deleteTarget?._id) return;
    try {
      setDeleting(true);
      await axios.delete(`${API}/roving-groups/${deleteTarget._id}`);
      notify("Roving package deleted.");
      setDeleteTarget(null);
      await fetchGroups();
    } catch (e) {
      console.error("Failed to delete roving package:", e);
      notify("Failed to delete. Please try again.", "error");
    } finally {
      setDeleting(false);
    }
  };

  // ── Export ─────────────────────────────────────────────────────────────────
  const handleExport = () => {
    const XLSX = require("sheetjs-style");

    const headers = [
      "Roving ID",
      "Region",
      "Account Supervisor",
      "Roving Outlet",
    ];

    // One row PER OUTLET. Roving ID simply repeats on each row.
    const aoa = [];
    rows.forEach((pkg) => {
      const names = pkg._memberNames.length ? pkg._memberNames : [""];
      names.forEach((outletName) => {
        aoa.push([pkg.rovingId, pkg.region, pkg.accountSupervisor, outletName]);
      });
    });

    const ws = XLSX.utils.aoa_to_sheet([headers, ...aoa]);
    ws["!cols"] = [{ wch: 12 }, { wch: 10 }, { wch: 22 }, { wch: 60 }];

    // Header styling
    headers.forEach((_, col) => {
      const cell = XLSX.utils.encode_cell({ r: 0, c: col });
      if (ws[cell])
        ws[cell].s = {
          font: { bold: true, color: { rgb: "FFFFFF" } },
          fill: { fgColor: { rgb: "2E6385" } },
          alignment: { horizontal: "center", vertical: "center" },
        };
    });

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Roving Packages");
    const buffer = XLSX.write(wb, { type: "array", bookType: "xlsx" });
    const blob = new Blob([buffer], {
      type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `EFC_Roving-Packages_${new Date().toISOString().split("T")[0]}.xlsx`;
    link.click();

    // Log the export to Recent Activity + notifications (same route as before).
    (async () => {
      try {
        await axios.post(`${API}/log-export`, {
          exportName: "EFC Roving Packages Export",
          rowCount: rows.length,
          clientAssigned: "ECOSSENTIAL FOODS CORP",
          updatedBy: localStorage.getItem("adminFullName") || "Unknown",
          updatedByRole: role || "",
        });
      } catch (err) {
        console.error("Failed to log export activity:", err);
      }
    })();
  };

  // ── Columns (one row = one roving package) ──────────────────────────────────
  const columns = [
    {
      field: "count",
      headerName: "#",
      width: 60,
      headerAlign: "center",
      align: "center",
    },
    {
      field: "rovingId",
      headerName: "Roving ID",
      width: 130,
      renderCell: (p) => (
        <Chip
          label={p.row.rovingId}
          size="small"
          sx={{
            fontWeight: 700,
            backgroundColor: "#e3f2fd",
            color: "#1565c0",
            fontFamily: "monospace",
          }}
        />
      ),
    },
    { field: "region", headerName: "Region", width: 100 },
    {
      field: "accountSupervisor",
      headerName: "Account Supervisor",
      width: 200,
    },
    {
      field: "outlets",
      headerName: "Roving Outlets",
      width: 520,
      sortable: false,
      renderCell: (p) => (
        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            gap: 0.3,
            py: 0.5,
            height: "100%",
          }}
        >
          <Typography
            variant="caption"
            sx={{ color: "#64748b", fontWeight: 600 }}
          >
            {p.row._memberNames.length} outlets merged
          </Typography>
          <Box sx={{ display: "flex", flexWrap: "wrap", gap: 0.5 }}>
            {p.row._memberNames.map((name) => (
              <Chip
                key={name}
                label={name}
                size="small"
                sx={{
                  height: 18,
                  fontSize: "10px",
                  maxWidth: 230,
                  backgroundColor: "#eceff1",
                  color: "#455a64",
                  fontWeight: 500,
                }}
              />
            ))}
          </Box>
        </Box>
      ),
    },
    {
      field: "actions",
      headerName: "Actions",
      width: 120,
      sortable: false,
      headerAlign: "center",
      align: "center",
      renderCell: (p) =>
        canEdit ? (
          <Box sx={{ display: "flex", gap: 0.5 }}>
            <Tooltip title="Edit package">
              <IconButton
                size="small"
                color="primary"
                onClick={() => openEdit(p.row._raw)}
              >
                <EditIcon fontSize="small" />
              </IconButton>
            </Tooltip>
            <Tooltip title="Delete package">
              <IconButton
                size="small"
                sx={{ color: "#c62828" }}
                onClick={() => setDeleteTarget(p.row._raw)}
              >
                <CloseIcon fontSize="small" />
              </IconButton>
            </Tooltip>
          </Box>
        ) : (
          <Tooltip title="View only">
            <LockIcon sx={{ fontSize: 16, color: "#b0bec5" }} />
          </Tooltip>
        ),
    },
  ];

  // ── Render ───────────────────────────────────────────────────────────────
  return (
    <>
      <Topbar />
      <Sidebar />
      <Box
        sx={{
          marginLeft: { xs: 0, md: sidebarOpen ? "280px" : "70px" },
          transition: "margin-left 0.3s ease",
          minHeight: "100vh",
          backgroundColor: "#f5f7fa",
          paddingTop: "64px",
        }}
      >
        <Box sx={{ p: 3, maxWidth: "1800px", margin: "0 auto" }}>
          {/* Header */}
          <Paper
            elevation={0}
            sx={{
              background: "linear-gradient(135deg, #1e3a5f 0%, #2c5282 100%)",
              borderRadius: 3,
              p: 3,
              mb: 3,
              color: "white",
              display: "flex",
              alignItems: "center",
              gap: 2,
            }}
          >
            <Avatar
              src={EFClogo}
              variant="rounded"
              sx={{ width: 56, height: 56, bgcolor: "rgba(255,255,255,0.15)" }}
            />
            <Box sx={{ flexGrow: 1 }}>
              <Typography variant="h5" sx={{ fontWeight: 700 }}>
                EFC Roving Outlets
              </Typography>
              <Typography variant="body2" sx={{ opacity: 0.9 }}>
                Group roving outlets into packages — each gets an auto Roving ID
              </Typography>
            </Box>
            {canEdit && (
              <Button
                variant="contained"
                startIcon={<AddIcon />}
                onClick={openCreate}
                sx={{
                  backgroundColor: "#fff",
                  color: "#1e3a5f",
                  fontWeight: 700,
                  "&:hover": { backgroundColor: "#e2e8f0" },
                }}
              >
                Create Roving Package
              </Button>
            )}
          </Paper>

          {/* Stat tiles */}
          <Grid container spacing={2} sx={{ mb: 3 }}>
            <Grid item xs={6} md={3}>
              <Card
                elevation={0}
                sx={{ border: "1px solid #e2e8f0", borderRadius: 2 }}
              >
                <CardContent>
                  <Typography
                    variant="caption"
                    sx={{ color: "#64748b", fontWeight: 600 }}
                  >
                    TOTAL ROVING PACKAGES
                  </Typography>
                  <Typography
                    variant="h4"
                    sx={{ fontWeight: 700, color: "#1e3a5f" }}
                  >
                    {totalPackages}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={6} md={3}>
              <Card
                elevation={0}
                sx={{ border: "1px solid #e2e8f0", borderRadius: 2 }}
              >
                <CardContent>
                  <Typography
                    variant="caption"
                    sx={{ color: "#64748b", fontWeight: 600 }}
                  >
                    OUTLETS COVERED
                  </Typography>
                  <Typography
                    variant="h4"
                    sx={{ fontWeight: 700, color: "#2e6385" }}
                  >
                    {totalOutlets}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          </Grid>

          {/* Action bar + filters */}
          <Paper
            elevation={0}
            sx={{ border: "1px solid #e2e8f0", borderRadius: 2, p: 2, mb: 2 }}
          >
            <Box
              sx={{
                display: "flex",
                flexWrap: "wrap",
                gap: 2,
                alignItems: "center",
              }}
            >
              <TextField
                size="small"
                placeholder="Search roving ID, package, outlet, supervisor…"
                value={searchText}
                onChange={(e) => setSearchText(e.target.value)}
                InputProps={{
                  startAdornment: (
                    <SearchIcon sx={{ mr: 1, color: "#94a3b8" }} />
                  ),
                }}
                sx={{ minWidth: 320, flexGrow: 1 }}
              />
              <FormControl size="small" sx={{ minWidth: 140 }}>
                <InputLabel>Region</InputLabel>
                <Select
                  label="Region"
                  value={filterRegion}
                  onChange={(e) => setFilterRegion(e.target.value)}
                >
                  <MenuItem value="ALL">All Regions</MenuItem>
                  {regionOptions.map((r) => (
                    <MenuItem key={r} value={r}>
                      {r}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
              <FormControl size="small" sx={{ minWidth: 200 }}>
                <InputLabel>Account Supervisor</InputLabel>
                <Select
                  label="Account Supervisor"
                  value={filterSupervisor}
                  onChange={(e) => setFilterSupervisor(e.target.value)}
                >
                  <MenuItem value="ALL">All Supervisors</MenuItem>
                  {supervisorOptions.map((s) => (
                    <MenuItem key={s} value={s}>
                      {s}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
              <Button
                variant="outlined"
                startIcon={<FileDownloadIcon />}
                onClick={handleExport}
                sx={{ color: "#2E6385", borderColor: "#2E6385" }}
              >
                Export
              </Button>
            </Box>
          </Paper>

          {/* Grid */}
          <Paper
            elevation={0}
            sx={{ border: "1px solid #e2e8f0", borderRadius: 2 }}
          >
            <DataGrid
              autoHeight
              rows={rows}
              columns={columns}
              getRowId={(r) => r.id}
              getRowHeight={() => "auto"}
              loading={loading}
              pageSizeOptions={[10, 25, 50, 100]}
              initialState={{
                pagination: { paginationModel: { pageSize: 25 } },
              }}
              sx={{
                border: "none",
                "& .MuiDataGrid-columnHeaders": {
                  backgroundColor: "#f1f5f9",
                  fontWeight: 700,
                },
                "& .MuiDataGrid-cell": {
                  alignItems: "flex-start",
                  py: 1,
                },
              }}
            />
          </Paper>
        </Box>
      </Box>

      {/* ── Create / Edit Roving Package modal ─────────────────────────────── */}
      <Dialog
        open={openGroupModal}
        onClose={closeGroupModal}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle sx={{ fontWeight: 700, color: "#1e3a5f" }}>
          {editingGroup ? "Edit Roving Package" : "Create Roving Package"}
          <IconButton
            onClick={closeGroupModal}
            sx={{ position: "absolute", right: 12, top: 12 }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent dividers>
          {formError && (
            <Alert severity="error" sx={{ mb: 2 }}>
              {formError}
            </Alert>
          )}
          {editingGroup?.rovingId && (
            <Alert severity="info" sx={{ mb: 2 }}>
              Roving ID: <strong>{editingGroup.rovingId}</strong> (assigned
              automatically — cannot be changed)
            </Alert>
          )}
          <Grid container spacing={2}>
            <Grid item xs={12} md={6}>
              <FormControl fullWidth size="small">
                <InputLabel>Account Supervisor *</InputLabel>
                <Select
                  label="Account Supervisor *"
                  value={groupSupervisor}
                  onChange={(e) => setGroupSupervisor(e.target.value)}
                >
                  {supervisorOptions.map((s) => (
                    <MenuItem key={s} value={s}>
                      {s}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12}>
              <Autocomplete
                multiple
                options={RUNTIME_OUTLETS}
                value={groupOutlets}
                onChange={(e, v) => setGroupOutlets(v)}
                getOptionLabel={(o) => o.outlet || ""}
                isOptionEqualToValue={(a, b) => a.id === b.id}
                filterSelectedOptions
                renderInput={(params) => (
                  <TextField
                    {...params}
                    label="Roving Outlets * (select 2 or more)"
                    placeholder="Add outlet…"
                    size="small"
                  />
                )}
                renderOption={(props, o) => (
                  <li {...props} key={o.id}>
                    <Box>
                      <Typography variant="body2" sx={{ fontWeight: 600 }}>
                        {o.outlet}
                      </Typography>
                      <Typography variant="caption" sx={{ color: "#64748b" }}>
                        {o.region} · {o.accountSupervisor}
                      </Typography>
                    </Box>
                  </li>
                )}
              />
              <FormHelperText>
                These outlets are merged into one roving package. A Roving ID is
                generated automatically on save.
              </FormHelperText>
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions sx={{ p: 2 }}>
          <Button
            onClick={closeGroupModal}
            startIcon={<CancelIcon />}
            disabled={saving}
          >
            Cancel
          </Button>
          <Button
            variant="contained"
            onClick={saveGroup}
            startIcon={<SaveIcon />}
            disabled={saving}
            sx={{
              backgroundColor: "#2E6385",
              "&:hover": { backgroundColor: "#1e4a66" },
            }}
          >
            {saving ? "Saving…" : editingGroup ? "Update" : "Create"}
          </Button>
        </DialogActions>
      </Dialog>

      {/* ── Delete confirm ─────────────────────────────────────────────────── */}
      <Dialog
        open={!!deleteTarget}
        onClose={() => !deleting && setDeleteTarget(null)}
      >
        <DialogTitle sx={{ fontWeight: 700 }}>
          Delete roving package?
        </DialogTitle>
        <DialogContent>
          <Typography variant="body2">
            This will remove{" "}
            <strong>
              {deleteTarget?.rovingId ? `${deleteTarget.rovingId} — ` : ""}
              {deleteTarget?.name}
            </strong>
            . The outlets themselves are not affected.
          </Typography>
        </DialogContent>
        <DialogActions sx={{ p: 2 }}>
          <Button onClick={() => setDeleteTarget(null)} disabled={deleting}>
            Cancel
          </Button>
          <Button
            variant="contained"
            onClick={confirmDelete}
            disabled={deleting}
            sx={{
              backgroundColor: "#c62828",
              "&:hover": { backgroundColor: "#8e1c1c" },
            }}
          >
            {deleting ? "Deleting…" : "Delete"}
          </Button>
        </DialogActions>
      </Dialog>

      {/* ── Snackbar ───────────────────────────────────────────────────────── */}
      <Snackbar
        open={snack.open}
        autoHideDuration={3500}
        onClose={() => setSnack((s) => ({ ...s, open: false }))}
        anchorOrigin={{ vertical: "bottom", horizontal: "center" }}
      >
        <Alert
          severity={snack.sev}
          onClose={() => setSnack((s) => ({ ...s, open: false }))}
          sx={{ width: "100%" }}
        >
          {snack.msg}
        </Alert>
      </Snackbar>
    </>
  );
}
